package com.portfolio.features.integration.github.client;
import java.time.*; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.core.ParameterizedTypeReference; import org.springframework.stereotype.Component; import org.springframework.web.client.*;
@Component public class GitHubApiClient { private final RestClient client; public GitHubApiClient(@Value("${app.github.api-base-url:https://api.github.com}") String base){client=RestClient.builder().baseUrl(base).defaultHeader("Accept","application/vnd.github+json").build();} public List<Repository> repos(String token,int page,int size){return call(()->client.get().uri(b->b.path("/user/repos").queryParam("page",page).queryParam("per_page",size).queryParam("sort","updated").queryParam("direction","desc").build()).header("Authorization","Bearer "+token).retrieve().body(new ParameterizedTypeReference<List<Repository>>(){}));} public Repository repo(String token,long id){return call(()->client.get().uri("/repositories/{id}",id).header("Authorization","Bearer "+token).retrieve().body(Repository.class));} public Map<String,Long> languages(String token,String owner,String name){return call(()->client.get().uri("/repos/{owner}/{name}/languages",owner,name).header("Authorization","Bearer "+token).retrieve().body(new ParameterizedTypeReference<Map<String,Long>>(){}));} private <T>T call(java.util.function.Supplier<T>s){try{return s.get();}catch(HttpClientErrorException.Unauthorized e){throw new IllegalArgumentException("GitHub connection has expired. Please reconnect GitHub.");}catch(HttpClientErrorException.Forbidden e){throw new IllegalArgumentException("GitHub API rate limit reached. Please try again later.");}catch(HttpServerErrorException e){throw new IllegalArgumentException("GitHub is temporarily unavailable.");}catch(RestClientException e){throw new IllegalArgumentException("Unable to reach GitHub.");}} public record Repository(long id,String name,String full_name,String description,String html_url,String homepage,String language,int stargazers_count,int forks_count,boolean private_,boolean fork,boolean archived,OffsetDateTime updated_at){} }
